// Redact common PII patterns BEFORE sending text to any model or storing it.
// Regex redaction is a baseline, not a guarantee. See Microsoft Presidio for stronger detection.
const patterns = [
  { label: 'EMAIL', re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g },
  { label: 'CARD', re: /\b(?:\d[ -]?){13,19}\b/g },
  { label: 'IBAN', re: /\b[A-Z]{2}\d{2}[A-Z0-9]{11,30}\b/g },
  { label: 'PHONE', re: /(?:\+\d{1,3}[ -]?)?\(?\d{3}\)?[ -]\d{3}[ -]\d{4}\b/g }
];
return $input.all().map(item => {
  let text = item.json.text || '';
  const counts = {};
  for (const p of patterns) {
    const m = text.match(p.re);
    counts[p.label] = m ? m.length : 0;
    text = text.replace(p.re, `[${p.label}_REDACTED]`);
  }
  return { json: { ...item.json, redacted_text: text, redactions: counts } };
});

