// Deterministic validation. The model extracts; code decides.
const cfg = $('Config').first().json;
const red = $('Redact PII').first().json;
return $input.all().map(item => {
  const f = item.json.output || {};
  const checks = {
    has_vendor: !!f.vendor_name,
    has_invoice_number: !!f.invoice_number,
    valid_date: /^\d{4}-\d{2}-\d{2}$/.test(f.invoice_date || ''),
    valid_currency: /^[A-Z]{3}$/.test(f.currency || ''),
    positive_total: typeof f.total === 'number' && f.total > 0,
    totals_add_up: typeof f.subtotal === 'number' && typeof f.tax === 'number' && f.subtotal > 0
      ? Math.abs((f.subtotal + f.tax) - f.total) < 0.02 : false
  };
  const passed = Object.values(checks).filter(Boolean).length;
  const confidence = Math.round((passed / Object.keys(checks).length) * 1000) / 1000;
  const issues = Object.entries(checks).filter(([, ok]) => !ok).map(([k]) => k);
  return { json: {
    doc_id: cfg.doc_id,
    doc_type: f.doc_type || 'other',
    fields: f,
    checks, issues, confidence,
    redactions: red.redactions,
    status: confidence >= cfg.confidence_threshold ? 'auto_approved' : 'needs_review'
  } };
});

